/*
 * A205112  Ordered differences of Lucas numbers.
 * https://oeis.org/A205112
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, changed
 * Formula:   a(n) = L(i) - L(j) where (i,j) are given by * i = smallest
 *            integer with i*(i-1)/2 >= n, * j = n - (i-1)*(i-2)/2 (1 <= j <=
 *            i-1) * L(k) denotes the k-th Lucas number: L(0)=2, L(1)=1, *
 *            L(k)=L(k-1)+L(k-2) for k>=2 * The sequence is generated by
 *            enumerating all differences * L(i)-L(j) for i>j in lex...
 * Range:     u8 n <= 55, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n)
{
    /* find i such that i*(i-1)/2 >= n */
    idx_t i = 2;
    for (;; ++i) {
        idx_t terms_up = (i * (i - 1)) / 2;
        if (terms_up >= n) break;
    }

    idx_t prev_terms = ((i - 1) * (i - 2)) / 2; /* terms before this i */
    idx_t j = n - prev_terms;                   /* position j for this i */

    /* compute Lucas numbers up to i, keep L(i) and L(j) */
    seq_t Lprev2 = (seq_t)2; /* L(0) */
    seq_t Lprev1 = (seq_t)1; /* L(1) */
    seq_t Li = 0, Lj = 0;

    /* handle j==1 directly */
    if (j == 1) Lj = (seq_t)1;
    /* handle i==0 or i==1 explicitly (never occurs for n>=1) */
    if (i == 0) Li = (seq_t)2;
    else if (i == 1) Li = (seq_t)1;
    else {
        seq_t cur;
        for (idx_t k = 2; k <= i; ++k) {
            cur = Lprev1 + Lprev2;            /* L(k) */
            if (k == j && j >= 2) Lj = cur;   /* capture L(j) if needed */
            if (k == i) Li = cur;             /* capture L(i) */
            Lprev2 = Lprev1;
            Lprev1 = cur;
        }
    }

    /* result is the difference; it will always be positive */
    return Li - Lj;
}
